var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

static IResult Greet(HttpRequest request, Func<string, string> format)
{
    if (!request.Query.TryGetValue("name", out var nameValues) || string.IsNullOrWhiteSpace(nameValues.ToString()))
    {
        return Results.BadRequest(new { error = "name is required" });
    }
    var raw = nameValues.ToString().Trim();
    var normalized = char.ToUpperInvariant(raw[0]) + raw.Substring(1).ToLowerInvariant();
    return Results.Ok(new { greeting = format(normalized) });
}

app.MapGet("/greet/formal", (HttpRequest request) => Greet(request, n => $"Good day, {n}."));
app.MapGet("/greet/casual", (HttpRequest request) => Greet(request, n => $"Hey {n}!"));

app.Run("http://0.0.0.0:8054");
